const model = `person "Customer" {
    "A customer of the online store"
}

softwareSystem "Online Store" {
    "Sells products to customers"
    components {
        component "Web Storefront" {
            "The customer-facing web application"
        }
        component "Order Service" {
            "Handles order processing"
        }
        component "Payments" {
            "Processes payments"
        }
        component "Product Database" {
            "Stores product and order data"
        }
    }
}

softwareSystem "Payment Gateway" {
    "Third-party payment processing"
}

Customer -> WebStorefront "Browses and purchases products"
WebStorefront -> OrderService "Places orders"
OrderService -> Payments "Charges cards"
Payments -> PaymentGateway "Processes payments"
OrderService -> ProductDatabase "Persists orders"
WebStorefront -> ProductDatabase "Reads the product catalog"`;

const views = `systemContext "Online Store" "System context view of the Online Store" {
    include * and their relationships
    autoLayout
}

container "Online Store" "Container view of the Online Store" {
    include * and their relationships
    autoLayout
}

component "Online Store" "Component view of the Online Store" {
    include * and their relationships
    autoLayout
}

theme default`;

const wrap = (withDocs) => `workspace "Team Workspace" {
    model {
${model}
    }
    views {
${views}
    }
${withDocs ? "    !docs docs/\n" : ""}}`;

const isErr = (v) => typeof v === "string" && /not permitted|error/i.test(v);

let dsl = wrap(true);
let parse = await tools.structurizr.parse({ dsl });
if (isErr(parse)) {
  dsl = wrap(false);
  parse = await tools.structurizr.parse({ dsl });
}
const validate = await tools.structurizr.validate({ dsl });
let inspect;
try { inspect = await tools.structurizr.inspect({ dsl }); } catch (e) { inspect = String(e); }

return { usedDocsDirective: dsl.includes("!docs"), parse, validate, inspect };

